#!/usr/bin/env python3
"""One upload: guarded TEST lifecycle code, public entry point and read-only reconciliation job."""
import base64, fcntl, hashlib, json, os, pwd, re, sqlite3, stat, subprocess, sys, tempfile, types, zlib
from pathlib import Path
BASE = ''
BASE_SHA = 'd2a3a18882e2dc66ed24ce347759402cc482910b03d7c0e3a8f84e1fc7d4b83e'
BUNDLE = ''
BUNDLE_SHA = 'ef3551169af296ca3de64c30f70dc6d62e45bdc3d40116292275a046fe7cf2b2'
RELEASE='appointment-management-20260928'
REVISION='20260928-r1'
JOURNAL='appointment-management-install.json'
ACTIVATION='booking-lifecycle.json'
MANIFEST='appointment-management-release.json'
PUBLIC=Path('/home/sitesee/public_html/re')
CRON=Path('/etc/cron.d/sitesee-booking-reconcile')
CONFIG={'schema':1,'stage':'test','enabled':True,'recipient':'cro@sitesee.ai'}

def modules():
 raw=zlib.decompress(base64.b64decode(BASE))
 if hashlib.sha256(raw).hexdigest()!=BASE_SHA:raise RuntimeError('Installer helper integrity differs.')
 w=types.ModuleType('reviewed_workflow');w.__file__=__file__;exec(compile(raw,'reviewed-workflow','exec'),w.__dict__)
 s,r,m=w.modules();return w,s,r,m

def bundle(m):
 raw=zlib.decompress(base64.b64decode(BUNDLE));m.need(m.digest(raw)==BUNDLE_SHA,'Payload integrity differs.')
 data=json.loads(raw);return {k:v.encode() for k,v in data['files'].items()},data['before']

def cron_bytes(m):
 return ('# SiteSee TEST lifecycle: provider reads only; never sends invitations or changes payments.\n'
  '*/5 * * * * sitesee umask 077; /usr/bin/flock -n /home/sitesee/.sitesee-real-estate/lifecycle-worker.lock '
  +str(m.PHP)+' /home/sitesee/.sitesee-real-estate/server/booking-lifecycle-reconcile.php '
  '>> /home/sitesee/.sitesee-real-estate/lifecycle-reconcile.log 2>&1\n').encode()

def destination(m,root,name,public=PUBLIC,cron=CRON):
 if name=='public/manage-appointment.php':return m.safe_path(public,'manage-appointment.php')
 if name=='cron/reconcile':return cron
 return m.safe_path(root,name)

def inventory(w,s,r,m,root,public,cron,php,uid,files,before,account=None,credentials=None):
 report=r.inventory(m,root,m.payload(),php,uid,account=account,credentials=credentials)
 old_workflow,_=w.bundle(m);old_scheduling,_=s.bundle(m)
 for name,expected in before.items():
  data=report.file(root/name)
  if data is not None and m.digest(data) not in {expected,m.digest(files[name]) if name in files else expected}:report.issue('Unreviewed application dependency preserved: '+name)
  report.readable.add(root/name)
 for name,data in files.items():
  if name.startswith('public/'):continue
  current=report.file(root/name,optional=True)
  if name not in before and current is not None and current!=data:report.issue('Unrelated additive file preserved: '+name)
  if current is not None:report.readable.add(root/name)
 for name,release,old in [('microsoft-scheduling-release.json',s.RELEASE,dict(old_scheduling,**old_workflow)),('booking-workflow-release.json',w.RELEASE,old_workflow)]:
  manifest=report.json(root/name,private=True)
  hashes={n:m.digest(b) for n,b in old.items()};updated=dict(hashes);updated.update({n:m.digest(b) for n,b in files.items() if not n.startswith('public/')})
  if manifest is not None and (manifest.get('release')!=release or manifest.get('files') not in (hashes,updated)):report.issue('Established release manifest differs: '+name)
 for name,expected in [(s.ACTIVATION,s.activation(m)),(ACTIVATION,m.encode(CONFIG))]:
  current=report.file(root/name,private=True,optional=name==ACTIVATION)
  if current is not None and current!=expected:report.issue('TEST activation differs: '+name)
 for name in ('zoho-calendar.json','zoho-confirmation.json','zoho-crm.json','booking-mail.json'):
  c=report.json(root/name,private=True);report.readable.add(root/name)
  if c is not None:
   if name.startswith('zoho-') and name!='zoho-crm.json' and (not re.fullmatch(r'[a-f0-9]{32}',str(c.get('calendar_uid',''))) or not c.get('enabled')):report.issue('Legacy calendar configuration differs: '+name)
   if name=='booking-mail.json' and c.get('enabled') is not True:report.issue('Established TEST sender is not enabled.')
   if name=='zoho-crm.json' and not (all(isinstance(c.get(k),str) and c[k] for k in ('client_id','client_secret','refresh_token','org_id','user_id')) and c.get('sync_mode')=='api' and c.get('original_sync_mode')=='api' and c.get('sync_reviewed_at') and c.get('owner_verified_at') and c.get('api_domain')=='https://www.zohoapis.com' and c.get('accounts_domain')=='https://accounts.zoho.com'):report.issue('Established CRM configuration differs.')
 report.guarded('Read-only booking schema',lambda:w.database_check(s,m,root))
 report.directory(public,trust_root=True)
 pub=report.file(public/'manage-appointment.php',optional=True)
 if pub is not None and pub!=files['public/manage-appointment.php']:report.issue('Unknown public management endpoint preserved.')
 def cron_check():
  p=cron.parent;info=p.lstat();m.need(stat.S_ISDIR(info.st_mode) and not info.st_mode&0o022 and info.st_uid==0,'Cron directory is unsafe.')
  if cron.exists() or cron.is_symlink():m.need(m.private_bytes(cron,0,private=False)==cron_bytes(m),'Existing cron file differs; preserved.')
 report.guarded('Reconciliation job',cron_check)
 record=report.json(root/MANIFEST,private=True,optional=True)
 expected={'release':RELEASE,'revision':REVISION,'files':{n:m.digest(b) for n,b in files.items()}}
 if record is not None and record!=expected:report.issue('Lifecycle release manifest differs.')
 with tempfile.TemporaryDirectory(prefix='sitesee-lifecycle-lint-') as folder:
  for name,data in files.items():
   def lint(name=name,data=data):
    path=Path(folder)/Path(name).name;path.write_bytes(data)
    p=subprocess.run([php,'-l',str(path)],stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=30);m.need(p.returncode==0,'PHP syntax failed: '+name)
   report.guarded('Lifecycle syntax',lint)
 return report

def desired(m,root,files):
 values={n:b for n,b in files.items() if n not in ('server/booking-staff.php','public/manage-appointment.php')}
 for name in ('calendar-confirmation-release.json','microsoft-scheduling-release.json','booking-workflow-release.json'):
  record=json.loads(m.private_bytes(root/name,root.stat().st_uid,private=False));record['files'].update({n:m.digest(b) for n,b in files.items() if not n.startswith('public/')});values[name]=m.encode(record)
 values[MANIFEST]=m.encode({'release':RELEASE,'revision':REVISION,'files':{n:m.digest(b) for n,b in files.items()}})
 values['server/booking-staff.php']=files['server/booking-staff.php'];values['public/manage-appointment.php']=files['public/manage-appointment.php'];values['cron/reconcile']=cron_bytes(m)
 values[ACTIVATION]=m.encode(CONFIG);return values

def read_target(m,path,uid):
 return m.private_bytes(path,uid,private=False) if path.exists() or path.is_symlink() else None

def write_target(m,path,data,uid,gid,public=False):
 m.atomic_write(path,data,uid,gid)
 if public:os.chmod(str(path),0o644)

def recover(m,root,uid,gid,values,check=False,public=PUBLIC,cron=CRON):
 path=root/JOURNAL
 if not path.exists():return
 j=json.loads(m.private_bytes(path,uid));m.need(j.get('release')==RELEASE and j.get('revision')==REVISION and j.get('state') in ('prepared','installed','restored'),'Recovery journal differs.')
 if j['state']!='prepared':return
 m.need(set(j.get('entries',{}))==set(values) and re.fullmatch(r'appointment-management-[A-Za-z0-9_-]+',j.get('backup','')),'Recovery paths differ.')
 folder=m.safe_path(root,'deployment-backups/'+j['backup']);old={}
 for name,entry in j['entries'].items():
  target=destination(m,root,name,public,cron);data=read_target(m,target,0 if name=='cron/reconcile' else uid)
  m.need((m.digest(data) if data is not None else None) in (entry['old'],entry['new']),'Unrelated concurrent edit preserved: '+name)
  b=m.private_bytes(folder/name,os.geteuid()) if entry['old'] is not None else None
  m.need(b is None or m.digest(b)==entry['old'],'Backup integrity differs: '+name);old[name]=b
 if (root/ACTIVATION).exists():
  m.need(all(read_target(m,destination(m,root,n,public,cron),0 if n=='cron/reconcile' else uid)==b for n,b in values.items()),'Lifecycle may be activated. Preserve code and journal; fix forward. Never restore old availability code.')
  if not check:j['state']='installed';m.atomic_write(path,m.encode(j),uid,gid)
  return
 m.need(not check,'Interrupted update: rerun this same installer to recover it.')
 order=['server/booking-staff.php','public/manage-appointment.php']+[n for n in values if n not in ('server/booking-staff.php','public/manage-appointment.php')]
 for name in order:
  target=destination(m,root,name,public,cron);b=old[name]
  if b is not None:write_target(m,target,b,0 if name=='cron/reconcile' else uid,0 if name=='cron/reconcile' else gid,name.startswith(('public/','cron/')))
  elif name in ('public/manage-appointment.php','cron/reconcile',ACTIVATION,MANIFEST) and target.exists():target.unlink()
  # Keep additive PHP modules for requests already executing. They have no active entry point after rollback.
 j['state']='restored';m.atomic_write(path,m.encode(j),uid,gid)

def deploy(m,root,values,uid,gid,public=PUBLIC,cron=CRON,write=None):
 write=write or write_target
 if all(read_target(m,destination(m,root,n,public,cron),0 if n=='cron/reconcile' else uid)==b for n,b in values.items()):return None
 m.need(not (root/ACTIVATION).exists(),'Activated lifecycle release differs. Do not overwrite or roll it back.')
 base=m.safe_path(root,'deployment-backups');base.mkdir(mode=0o700,exist_ok=True)
 folder=Path(tempfile.mkdtemp(prefix='appointment-management-',dir=str(base)));entries={}
 for name,data in values.items():
  target=destination(m,root,name,public,cron);old=read_target(m,target,0 if name=='cron/reconcile' else uid)
  if old is not None:
   p=folder/name;p.parent.mkdir(mode=0o700,parents=True,exist_ok=True);m.atomic_write(p,old,os.geteuid(),os.getegid())
  entries[name]={'old':m.digest(old) if old is not None else None,'new':m.digest(data)}
 j={'release':RELEASE,'revision':REVISION,'state':'prepared','backup':folder.name,'entries':entries};m.atomic_write(root/JOURNAL,m.encode(j),uid,gid)
 try:
  for name,data in values.items():
   target=destination(m,root,name,public,cron);old=read_target(m,target,0 if name=='cron/reconcile' else uid)
   m.need((m.digest(old) if old is not None else None)==entries[name]['old'],'Target changed during installation: '+name)
   write(m,target,data,0 if name=='cron/reconcile' else uid,0 if name=='cron/reconcile' else gid,name.startswith(('public/','cron/')))
  m.need(all(read_target(m,destination(m,root,n,public,cron),0 if n=='cron/reconcile' else uid)==b for n,b in values.items()),'Final release bytes differ.')
  j['state']='installed';m.atomic_write(root/JOURNAL,m.encode(j),uid,gid)
 except Exception:
  recover(m,root,uid,gid,values,public=public,cron=cron);raise
 return folder

def main():
 w,s,r,m=modules();files,before=bundle(m)
 m.need(sys.argv[1:] in ([],['--check']),'Use no arguments, or --check for local inspection.')
 m.need(os.geteuid()==0,'Run in WHM Terminal as root.');check=sys.argv[1:]==['--check'];os.umask(0o077)
 account=pwd.getpwnam('sitesee');uid,gid=account.pw_uid,account.pw_gid;root=m.ROOT
 print('SiteSee TEST Appointment Management | '+REVISION,flush=True)
 lock=os.open(str(root),os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW)
 calendar_lock=None
 try:
  fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
  # Existing release dictionaries determine backups; payload hashes independently pin every dependency.
  values=desired(m,root,files);recover(m,root,uid,gid,values,check)
  report=inventory(w,s,r,m,root,PUBLIC,CRON,m.PHP,uid,files,before,account)
  r.show_inventory(report,lambda text:print(text,flush=True));m.need(not report.errors,'All detected local blockers are listed above. Existing files preserved.')
  m.need(Path('/usr/bin/flock').is_file(),'Required flock utility is unavailable.')
  if check:print('FINAL RESULTS\nLocal inspection: PASS\nNo files, permissions, database rows or provider data changed.');return
  audit=r.apply_repairs(m,report,uid,gid)
  if audit:print('Permission recovery record: '+str(audit),flush=True)
  report=inventory(w,s,r,m,root,PUBLIC,CRON,m.PHP,uid,files,before,account)
  m.need(not report.errors and not report.repairs,'Post-repair inventory changed. Preserve recovery records.')
  lockpath=root/'booking-confirmation.lock';m.private_bytes(lockpath,uid)
  calendar_lock=os.open(str(lockpath),os.O_RDWR|os.O_NOFOLLOW);fcntl.flock(calendar_lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
  w.provider_reads(s,m,root,m.PHP,account)
  # Prove schema DDL on an in-memory database using the packaged source; no customer ledger opened here.
  with tempfile.TemporaryDirectory(prefix='sitesee-lifecycle-schema-') as folder:
   p=Path(folder)/'schema.php';p.write_bytes(files['server/booking-lifecycle-store.php'])
   code="require $argv[1];$db=new PDO('sqlite::memory:');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);booking_lifecycle_schema($db);echo 'PASS';"
   test=subprocess.run([m.PHP,'-r',code,str(p)],stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=30);m.need(test.returncode==0 and test.stdout==b'PASS','Additive schema validation failed.')
  backup=deploy(m,root,values,uid,gid)
  # No scheduling request runs until activation; database tables are additive on the next normal request.
  print('\nFINAL RESULTS\nAppointment management: INSTALLED IN TEST MODE')
  print('Customer management, staff controls and five-minute read-only reconciliation: installed')
  print('Microsoft / sender / Zoho CRM read preflight and release hashes: PASS')
  print('No booking, payment, event, invitation, email, credential or integration setting was changed.')
  print('Stripe remains TEST. Legacy Zoho appointment identities preserved.')
  print('Backup: '+str(backup) if backup else 'Existing installation: unchanged')
  print('Next: test a fresh paid TEST appointment. Do not resend D32FFC7458.')
  print('Browser changes, notices, cron execution and provider write behavior require operator verification.')
 finally:
  if calendar_lock is not None:os.close(calendar_lock)
  os.close(lock)

if __name__=='__main__':
 try:main()
 except Exception as e:
  print('\nFINAL RESULTS\nAppointment management: STOPPED')
  print(str(e) if type(e).__name__=='InstallError' else 'A check could not complete ('+type(e).__name__+').')
  print('Retain journals and backups. Rerun this same installer after review. Never restore old scheduling/payment code over an activated release.');sys.exit(1)
